function nodeInfo(node, depth) {
  const pad = '  '.repeat(depth);
  const t = node.type;
  let extra = '';
  if ('name' in node) extra += ' name=' + JSON.stringify(node.name);
  if ('width' in node) extra += ' size=' + Math.round(node.width) + 'x' + Math.round(node.height);
  if ('fills' in node && node.type !== 'TEXT') {
    const fills = node.fills.map(f => f.type === 'SOLID' ? `solid ${hex(f.color)} ${f.opacity!==undefined?f.opacity:1}` : f.type === 'IMAGE' ? 'image' : f.type);
    extra += ' fills=[' + fills.join(', ') + ']';
  } else if (node.type === 'TEXT') {
    const fn = typeof node.fontName === 'symbol' ? node.fontName : node.fontName;
    extra += ' text=' + JSON.stringify(node.characters) + ' font=' + (fn && JSON.stringify(fn)) + ' size=' + node.fontSize + ' fg=' + (node.fills[0] && node.fills[0].type==='SOLID'?hex(node.fills[0].color):'') + ' aligns=' + node.textAlignHorizontal + '/' + node.textAlignVertical;
  }
  if ('cornerRadius' in node) extra += ' radius=' + node.cornerRadius;
  if ('effects' in node && node.effects && node.effects.length) extra += ' effects=' + node.effects.length;
  let s = pad + t + extra;
  if ('children' in node && depth < 3) {
    for (const c of node.children) s += '\n' + nodeInfo(c, depth+1);
  }
  return s;
}

